//! Evaluation parameters: piece values, piece-square tables (midgame and
//! endgame) and the bishop-pair bonus.
//!
//! `TRAINED` is generated by tools/train_v2.py from the modern elite
//! corpus recovered into data/raw_batches (TWIC + PGN Mentor, games by
//! GM/WGM/IM/WIM/FM/WFM/CM/WCM players) using a Texel-style logistic
//! fit on game results only — no engine labels, no neural net.
//! `BASELINE` is the handcrafted pre-training parameter set inherited
//! from Anciency, kept so the tuned build can be measured against it
//! (UCI option "Baseline") — it is the "untuned" side of every
//! strength comparison in the README.
//!
//! PST layout: 64 entries per piece, rank 8 first (a8..h8, a7.., .. a1).
//! The evaluator indexes a White piece on square `sq` (a1 = 0) as
//! `pst[sq ^ 56]`, and a Black piece as `pst[sq]` (its vertically
//! mirrored square in the same layout). tools/train.py emits exactly
//! this layout.

#[derive(Clone, Copy)]
pub struct EvalParams {
    pub value_mg: [i32; 6], // P N B R Q K
    pub value_eg: [i32; 6],
    pub pst_mg: [[i32; 64]; 6],
    pub pst_eg: [[i32; 64]; 6],
    pub bishop_pair_mg: i32,
    pub bishop_pair_eg: i32,
    // Phase B (2.1.0) structural features — definitions live in
    // eval::extra_features and tools/quiet_features.py (the tuner's
    // reference implementation; the two must never drift apart).
    // All zero in BASELINE: the handcrafted set predates them.
    pub passed_mg: [i32; 6], // passed pawn by relative rank 2..7
    pub passed_eg: [i32; 6],
    pub isolated_mg: i32,
    pub isolated_eg: i32,
    pub doubled_mg: i32,
    pub doubled_eg: i32,
    pub backward_mg: i32,
    pub backward_eg: i32,
    pub shield_mg: i32,
    pub shield_eg: i32,
    pub king_attack_mg: [i32; 4], // by attacker type N B R Q
    pub king_attack_eg: [i32; 4],
    pub mobility_mg: [i32; 4], // by piece type N B R Q
    pub mobility_eg: [i32; 4],
    pub rook_open_mg: i32,
    pub rook_open_eg: i32,
    pub rook_semi_mg: i32,
    pub rook_semi_eg: i32,
    pub rook_seventh_mg: i32,
    pub rook_seventh_eg: i32,
    pub outpost_mg: i32,
    pub outpost_eg: i32,
}

